# test_partial.py
import pytest

from your_module import partial  # replace "your_module" with the module containing partial


def test_partial_binds_positional_arguments():
    def collect(*args, **kwargs):
        return args, kwargs

    wrapped = partial(collect, 1, 2)

    assert wrapped(3, 4) == ((1, 2, 3, 4), {})


def test_partial_binds_keyword_arguments():
    def greet(greeting, name, punctuation="!"):
        return f"{greeting}, {name}{punctuation}"

    wrapped = partial(greet, greeting="Hello", punctuation=".")

    assert wrapped(name="Ada") == "Hello, Ada."


def test_partial_mixes_bound_and_call_time_arguments():
    def func(a, b, c=0, *, d=0):
        return a, b, c, d

    wrapped = partial(func, 1, c=3, d=4)

    assert wrapped(2) == (1, 2, 3, 4)


def test_call_time_kwargs_override_bound_kwargs():
    def collect(*args, **kwargs):
        return args, kwargs

    wrapped = partial(collect, color="red", size="M")

    assert wrapped(color="blue") == (
        (),
        {
            "color": "blue",
            "size": "M",
        },
    )


def test_call_time_kwarg_override_does_not_mutate_bound_kwargs():
    def collect(*args, **kwargs):
        return kwargs

    wrapped = partial(collect, color="red")

    assert wrapped(color="blue") == {"color": "blue"}
    assert wrapped() == {"color": "red"}


def test_partial_with_no_bound_arguments_behaves_like_original_function():
    def collect(*args, **kwargs):
        return args, kwargs

    wrapped = partial(collect)

    assert wrapped(1, 2, key="value") == ((1, 2), {"key": "value"})


def test_partial_supports_keyword_only_arguments():
    def func(a, *, required_kw):
        return a, required_kw

    wrapped = partial(func, required_kw="bound")

    assert wrapped(10) == (10, "bound")


def test_missing_required_argument_raises_type_error():
    def func(a, b):
        return a + b

    wrapped = partial(func, 1)

    with pytest.raises(TypeError):
        wrapped()


def test_unexpected_keyword_argument_raises_type_error():
    def func(a):
        return a

    wrapped = partial(func)

    with pytest.raises(TypeError):
        wrapped(1, unexpected=True)


def test_duplicate_argument_value_raises_type_error():
    def func(a):
        return a

    wrapped = partial(func, 1)

    with pytest.raises(TypeError):
        wrapped(a=2)


def test_exception_from_wrapped_function_is_propagated():
    class CustomError(Exception):
        pass

    def func():
        raise CustomError("boom")

    wrapped = partial(func)

    with pytest.raises(CustomError, match="boom"):
        wrapped()
